package com.alibaba.fastjson2.writer;

import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONFactory;
import com.alibaba.fastjson2.JSONWriter;
import com.alibaba.fastjson2.annotation.JSONType;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Type;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Test for the fix where @JSONType(serializer = ...) on enum types
 * should set writeEnumAsJavaBean = true to ensure custom serializer is used.
 */
public class ObjectWriterBaseModuleEnumSerializerTest {

    // Custom serializer for testing
    public static class DictSerializer implements ObjectWriter<Enum<?>> {
        @Override
        public void write(JSONWriter jsonWriter, Object object, Object fieldName, Type fieldType, long features) {
            jsonWriter.writeString("custom_" + ((Enum<?>) object).name());
        }
    }

    // Test enum with @JSONType annotation specifying custom serializer
    @JSONType(serializer = DictSerializer.class)
    public enum AlarmStatus {
        OK, WARNING, ERROR
    }

    // Container class that has a field of the annotated enum type
    public static class AppDto {
        private AlarmStatus status;

        public AppDto(AlarmStatus status) {
            this.status = status;
        }

        public AlarmStatus getStatus() {
            return status;
        }

        public void setStatus(AlarmStatus status) {
            this.status = status;
        }
    }

    @Test
    public void testEnumWithCustomSerializerAsField() {
        // Create an instance with enum field
        AppDto dto = new AppDto(AlarmStatus.WARNING);

        // Serialize the object
        String json = JSON.toJSONString(dto);

        // Before the patch: the custom serializer would not be used,
        // so the enum would be serialized as a regular enum (e.g., "WARNING")
        // After the patch: the custom serializer should be invoked,
        // producing "custom_WARNING"

        // Assert that the custom serializer was used
        // The expected JSON depends on the default naming; assuming default field name "status"
        // The custom serializer writes "custom_" + enum name
        assertTrue(json.contains("custom_WARNING"), 
            "Custom serializer should be invoked for enum field. JSON: " + json);

        // More precise assertion: check the exact JSON structure
        // The default behavior serializes field name as "status"
        assertEquals("{\"status\":\"custom_WARNING\"}", json);
    }

    @Test
    public void testDirectEnumSerialization() {
        // Test direct serialization of the enum value
        String json = JSON.toJSONString(AlarmStatus.ERROR);

        // Before patch: might serialize as "ERROR" (default enum serialization)
        // After patch: should use custom serializer -> "custom_ERROR"
        assertEquals("\"custom_ERROR\"", json);
    }

    @Test
    public void testBeanInfoConfiguration() {
        // Get the ObjectWriter for the enum type to inspect its configuration
        // Use JSONFactory.getDefaultObjectWriterProvider() instead of JSON.getDefaultObjectWriter()
        ObjectWriter<AlarmStatus> writer = JSONFactory.getDefaultObjectWriterProvider().getObjectWriter(AlarmStatus.class);

        // The writer should be an instance of our custom serializer
        // In fastjson2, when a custom serializer is specified via @JSONType,
        // it should be wrapped or directly used.
        // We can verify by checking the serialization output
        JSONWriter jsonWriter = JSONWriter.of();
        writer.write(jsonWriter, AlarmStatus.OK, null, AlarmStatus.class, 0);
        String result = jsonWriter.toString();

        assertEquals("\"custom_OK\"", result);
    }

    @Test
    public void testEnumInList() {
        // Test serialization of a list containing the enum
        List<AlarmStatus> list = Arrays.asList(AlarmStatus.OK, AlarmStatus.WARNING);
        String json = JSON.toJSONString(list);

        // Should use custom serializer for each element
        assertEquals("[\"custom_OK\",\"custom_WARNING\"]", json);
    }

    @Test
    public void testEnumInMap() {
        // Test serialization of a map with enum values
        Map<String, AlarmStatus> map = new HashMap<>();
        map.put("key1", AlarmStatus.ERROR);
        map.put("key2", AlarmStatus.OK);

        String json = JSON.toJSONString(map);

        // The order might vary, so check for both entries
        assertTrue(json.contains("\"custom_ERROR\""));
        assertTrue(json.contains("\"custom_OK\""));
    }
}

