static boolean isValidArray(String text) {
        if (text == null || text.length() == 0) {
            return false;
        }
        if(!text.startsWith("[")){
            return false;
        }
        JSONReader jsonReader = JSONReader.of(text);
        try {
            if (!jsonReader.isArray()) {
                return false;
            }
            jsonReader.skipValue();
        } catch (JSONException error) {
            return false;
        }
        return true;
    }

