package com.alibaba.fastjson2;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class JSONIsValidTest {

    @Test
    public void testIsValid_NonJsonText() {
        // Test strings that don't start with '{' or '['
        assertFalse(JSON.isValid((String) "plain text"));
        assertFalse(JSON.isValid((String) "123"));
        assertFalse(JSON.isValid((String) "\"quoted string\""));
        assertFalse(JSON.isValid((String) "true"));
        assertFalse(JSON.isValid((String) "false"));
        assertFalse(JSON.isValid((String) "null"));
        assertFalse(JSON.isValid((String) ""));
        assertFalse(JSON.isValid((String) null));
    }

    @Test
    public void testIsValid_ValidJsonObject() {
        // Should return true for valid JSON objects
        assertTrue(JSON.isValid((String) "{}"));
        assertTrue(JSON.isValid((String) "{\"key\":\"value\"}"));
        assertTrue(JSON.isValid((String) "{\"a\":1,\"b\":2}"));
    }

    @Test
    public void testIsValid_ValidJsonArray() {
        // Should return true for valid JSON arrays
        assertTrue(JSON.isValid((String) "[]"));
        assertTrue(JSON.isValid((String) "[1,2,3]"));
        assertTrue(JSON.isValid((String) "[\"a\",\"b\"]"));
    }

    @Test
    public void testIsValid_InvalidJsonStructure() {
        // Should return false for malformed JSON even if it starts with '{' or '['
        assertFalse(JSON.isValid((String) "{"));
        assertFalse(JSON.isValid((String) "["));
        assertFalse(JSON.isValid((String) "{]"));
        assertFalse(JSON.isValid((String) "[}"));
        assertFalse(JSON.isValid((String) "{\"key\":}"));
    }

    @Test
    public void testIsValidArray_NonArrayText() {
        // Test strings that don't start with '['
        assertFalse(JSON.isValidArray((String) "plain text"));
        assertFalse(JSON.isValidArray((String) "123"));
        assertFalse(JSON.isValidArray((String) "\"quoted string\""));
        assertFalse(JSON.isValidArray((String) "{}"));
        assertFalse(JSON.isValidArray((String) "{\"key\":\"value\"}"));
        assertFalse(JSON.isValidArray((String) ""));
        assertFalse(JSON.isValidArray((String) null));
    }

    @Test
    public void testIsValidArray_ValidJsonArray() {
        // Should return true for valid JSON arrays
        assertTrue(JSON.isValidArray((String) "[]"));
        assertTrue(JSON.isValidArray((String) "[1,2,3]"));
        assertTrue(JSON.isValidArray((String) "[\"a\",\"b\"]"));
        assertTrue(JSON.isValidArray((String) "[{\"a\":1},{\"b\":2}]"));
    }

    @Test
    public void testIsValidArray_InvalidArrayStructure() {
        // Should return false for malformed JSON arrays
        assertFalse(JSON.isValidArray((String) "["));
        assertFalse(JSON.isValidArray((String) "[1,2,"));
        assertFalse(JSON.isValidArray((String) "[}"));
        assertFalse(JSON.isValidArray((String) "[,]"));
    }

    @Test
    public void testIsValidArray_StartsWithBracketButNotArray() {
        // Edge case: starts with '[' but contains invalid content
        assertFalse(JSON.isValidArray((String) "[invalid]"));
    }

    @Test
    public void testIsValid_StartsWithBraceOrBracketOnly() {
        // Single character cases
        assertFalse(JSON.isValid((String) "{"));
        assertFalse(JSON.isValid((String) "["));

        // Valid single element cases
        assertTrue(JSON.isValid((String) "{}"));
        assertTrue(JSON.isValid((String) "[]"));
    }

    @Test
    public void testIsValidArray_StartsWithBracketOnly() {
        // Single bracket case (invalid)
        assertFalse(JSON.isValidArray((String) "["));
    }

    @Test
    public void testIsValid_NumberStartingText() {
        // Numbers are valid JSON values but not valid JSON objects/arrays
        assertFalse(JSON.isValid((String) "123"));
        assertFalse(JSON.isValid((String) "3.14"));
        assertFalse(JSON.isValid((String) "-42"));
    }

    @Test
    public void testIsValidArray_NumberStartingText() {
        // Numbers shouldn't pass array validation
        assertFalse(JSON.isValidArray((String) "123"));
        assertFalse(JSON.isValidArray((String) "3.14"));
        assertFalse(JSON.isValidArray((String) "-42"));
    }

    @Test
    public void testIsValid_BooleanStartingText() {
        // Booleans are valid JSON values but not valid JSON objects/arrays
        assertFalse(JSON.isValid((String) "true"));
        assertFalse(JSON.isValid((String) "false"));
    }

    @Test
    public void testIsValidArray_BooleanStartingText() {
        // Booleans shouldn't pass array validation
        assertFalse(JSON.isValidArray((String) "true"));
        assertFalse(JSON.isValidArray((String) "false"));
    }

    @Test
    public void testIsValid_NullStartingText() {
        // Null is a valid JSON value but not a valid JSON object/array
        assertFalse(JSON.isValid((String) "null"));
    }

    @Test
    public void testIsValidArray_NullStartingText() {
        // Null shouldn't pass array validation
        assertFalse(JSON.isValidArray((String) "null"));
    }
}

