import org.junit.jupiter.api.Test;
import java.lang.reflect.Method;
import java.util.function.Function;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Test for the fix of casting org.bson.types.Decimal128 to Double.
 * This test verifies that the patch correctly handles conversion from Decimal128 to Double
 * by using the existing type conversion infrastructure.
 */
public class TypeUtilsDecimal128ToDoubleTest {

    /**
     * Test that the cast method correctly converts a Decimal128 object to Double
     * after the patch is applied. This test will fail before the patch because
     * the cast method would throw a JSONException when trying to cast Decimal128 to Double.
     */
    @Test
    public void testCastDecimal128ToDouble() throws Exception {
        // Simulate the scenario where we have a Decimal128 object
        // We need to create a mock Decimal128 instance because the actual class
        // might not be available in the test environment.
        // We'll use reflection to create an instance and set up the necessary mocks.

        // First, check if Decimal128 class is available. If not, we skip the test.
        Class<?> decimal128Class;
        try {
            decimal128Class = Class.forName("org.bson.types.Decimal128");
        } catch (ClassNotFoundException e) {
            // If Decimal128 is not in classpath, we cannot run the test.
            // This is acceptable because the test is for a specific integration scenario.
            return;
        }

        // Create a Decimal128 instance with value 123.45
        // Decimal128 has a constructor taking a BigDecimal
        java.math.BigDecimal bd = new java.math.BigDecimal("123.45");
        Object decimal128Obj = decimal128Class.getConstructor(java.math.BigDecimal.class).newInstance(bd);

        // Get the ObjectReaderProvider (default one)
        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();

        // Before the patch, this call would throw JSONException
        // After the patch, it should return a Double with value 123.45
        Double result = TypeUtils.cast(decimal128Obj, Double.class, provider);

        // Verify the conversion is correct
        assertNotNull(result, "Result should not be null");
        assertEquals(123.45, result, 0.0001, "Double value should match Decimal128 value");
    }

    /**
     * Test that the cast method still works for other types (non-Decimal128 to Double)
     * to ensure the patch doesn't break existing functionality.
     */
    @Test
    public void testCastOtherTypesToDouble() {
        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();

        // Test with BigDecimal (should work before and after patch)
        java.math.BigDecimal bd = new java.math.BigDecimal("123.45");
        Double result1 = TypeUtils.cast(bd, Double.class, provider);
        assertNotNull(result1);
        assertEquals(123.45, result1, 0.0001);

        // Test with Integer
        Integer intVal = 123;
        Double result2 = TypeUtils.cast(intVal, Double.class, provider);
        assertNotNull(result2);
        assertEquals(123.0, result2, 0.0001);

        // Test with String
        String strVal = "123.45";
        Double result3 = TypeUtils.cast(strVal, Double.class, provider);
        assertNotNull(result3);
        assertEquals(123.45, result3, 0.0001);
    }

    /**
     * Test the specific scenario described in the requirement:
     * Converting a JSONObject containing Decimal128 values to a Java object with Double fields.
     * This simulates the real-world use case of MongoDB storage and retrieval.
     */
    @Test
    public void testJSONObjectWithDecimal128ToJavaObject() throws Exception {
        // Check if Decimal128 class is available
        Class<?> decimal128Class;
        try {
            decimal128Class = Class.forName("org.bson.types.Decimal128");
        } catch (ClassNotFoundException e) {
            return; // Skip test if Decimal128 not available
        }

        // Create a Decimal128 instance
        java.math.BigDecimal bd = new java.math.BigDecimal("123.45");
        Object decimal128Obj = decimal128Class.getConstructor(java.math.BigDecimal.class).newInstance(bd);

        // Create a JSONObject with the Decimal128 value
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("holidayHour", decimal128Obj);

        // Define a simple Java class with a Double field
        class ImportRefinedMO {
            private Double holidayHour;
            public Double getHolidayHour() { return holidayHour; }
            public void setHolidayHour(Double holidayHour) { this.holidayHour = holidayHour; }
        }

        // Convert JSONObject to Java object
        // This internally uses TypeUtils.cast for field conversion
        ImportRefinedMO mo = jsonObject.toJavaObject(ImportRefinedMO.class);

        // Verify the conversion
        assertNotNull(mo, "Java object should not be null");
        assertNotNull(mo.getHolidayHour(), "holidayHour field should not be null");
        assertEquals(123.45, mo.getHolidayHour(), 0.0001, "holidayHour should be correctly converted from Decimal128");
    }

    /**
     * Test that the patch doesn't affect casting Decimal128 to other types.
     * Only Decimal128 to Double should be affected.
     */
    @Test
    public void testCastDecimal128ToOtherTypes() throws Exception {
        Class<?> decimal128Class;
        try {
            decimal128Class = Class.forName("org.bson.types.Decimal128");
        } catch (ClassNotFoundException e) {
            return;
        }

        java.math.BigDecimal bd = new java.math.BigDecimal("123.45");
        Object decimal128Obj = decimal128Class.getConstructor(java.math.BigDecimal.class).newInstance(bd);
        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();

        // Decimal128 to BigDecimal should work (if there's a converter)
        // This might throw an exception if no converter is registered, which is expected
        try {
            java.math.BigDecimal result = TypeUtils.cast(decimal128Obj, java.math.BigDecimal.class, provider);
            // If it doesn't throw, verify the value
            assertEquals(bd, result);
        } catch (Exception e) {
            // It's okay if this fails - the patch only fixes Decimal128 to Double
        }

        // Decimal128 to String should work via the general ObjectWriter path
        String strResult = TypeUtils.cast(decimal128Obj, String.class, provider);
        assertNotNull(strResult);
        // The string representation might vary, but it should not be empty
        assertFalse(strResult.isEmpty());
    }

    /**
     * Test edge cases: null Decimal128, very large/small values.
     */
    @Test
    public void testCastDecimal128EdgeCases() throws Exception {
        Class<?> decimal128Class;
        try {
            decimal128Class = Class.forName("org.bson.types.Decimal128");
        } catch (ClassNotFoundException e) {
            return;
        }

        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();

        // Test with very large value
        java.math.BigDecimal largeBd = new java.math.BigDecimal("1.23456789E+100");
        Object largeDecimal128 = decimal128Class.getConstructor(java.math.BigDecimal.class).newInstance(largeBd);
        Double largeResult = TypeUtils.cast(largeDecimal128, Double.class, provider);
        assertNotNull(largeResult);
        assertEquals(largeBd.doubleValue(), largeResult, 0.0001);

        // Test with very small value
        java.math.BigDecimal smallBd = new java.math.BigDecimal("1.23456789E-100");
        Object smallDecimal128 = decimal128Class.getConstructor(java.math.BigDecimal.class).newInstance(smallBd);
        Double smallResult = TypeUtils.cast(smallDecimal128, Double.class, provider);
        assertNotNull(smallResult);
        assertEquals(smallBd.doubleValue(), smallResult, 0.0001);

        // Test with zero
        java.math.BigDecimal zeroBd = java.math.BigDecimal.ZERO;
        Object zeroDecimal128 = decimal128Class.getConstructor(java.math.BigDecimal.class).newInstance(zeroBd);
        Double zeroResult = TypeUtils.cast(zeroDecimal128, Double.class, provider);
        assertNotNull(zeroResult);
        assertEquals(0.0, zeroResult, 0.0001);

        // Test with negative value
        java.math.BigDecimal negBd = new java.math.BigDecimal("-123.45");
        Object negDecimal128 = decimal128Class.getConstructor(java.math.BigDecimal.class).newInstance(negBd);
        Double negResult = TypeUtils.cast(negDecimal128, Double.class, provider);
        assertNotNull(negResult);
        assertEquals(-123.45, negResult, 0.0001);
    }
}

