            fail("Should throw UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected
        }
    }

    @Test
    public void testEnumSetDeserializationViaObjectReader() {
        EnumSet<TimeUnit> originalSet = EnumSet.of(TimeUnit.SECONDS, TimeUnit.MINUTES);
        byte[] jsonbBytes = JSONB.toBytes(originalSet);

        ObjectReader<EnumSet<TimeUnit>> reader = JSONFactory
            .getDefaultObjectReaderProvider()
            .getObjectReader(new TypeReference<EnumSet<TimeUnit>>() {}.getType());

        EnumSet<TimeUnit> deserializedSet = reader.readJSONBObject(
            JSONReader.ofJSONB(jsonbBytes),
            null,
            null,
            0
        );

